const scenario = "menyebar_jaringan"; // coba ubah ke: menyamar_sah atau mengenkripsi_meminta_tebusan

function classifyMalware(s) {
  if (s === "menyebar_jaringan") return "Worm";
  if (s === "menyamar_sah") return "Trojan Horse";
  if (s === "mengenkripsi_meminta_tebusan") return "Ransomware";
  return "Tidak diketahui";
}

const result = classifyMalware(scenario);
console.log("Ciri:", scenario);
console.log("Klasifikasi:", result);

const keyword = "worm"; // ganti jadi "trojan" atau "ransomware"

function malwareFromKeyword(k) {
  const map = {
    "worm": "Worm",
    "trojan": "Trojan Horse",
    "ransomware": "Ransomware"
  };
  return map[k] || "Tidak diketahui";
}

console.log("Keyword:", keyword);
console.log("Jawaban:", malwareFromKeyword(keyword));
